<?php

namespace Database\Seeders;

use App\Models\Template;
use App\Support\LandingTemplateVariables;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

/**
 * Seeds the centrally managed classic and Noja landing templates.
 *
 * @since 1.0.0
 * @since 2.1.0 Behavior updated for the 2.1.0 release.
 */
class TemplateSeeder extends Seeder
{
    public const CLASSIC_CODE = 'classic';

    public const NOJA_CODE = 'noja-kasht';

    /**
     * Seed the centrally managed landing templates.
     *
     * @return void No value is returned.
     *
     * @since 1.0.0
     * @since 2.1.0 Behavior updated for the 2.1.0 release.
     */
    public function run(): void
    {
        DB::transaction(function (): void {
            $classic = Template::query()->firstOrCreate(
                ['code' => self::CLASSIC_CODE],
                array_merge(self::classicContent(), [
                    'name' => __('messages.classic_template'),
                    'is_active' => true,
                    'is_default' => true,
                ])
            );

            $existingNoja = Template::query()->where('code', self::NOJA_CODE)->first();
            $nojaContent = self::nojaContent();

            if ($existingNoja) {
                foreach ([
                    'seo_title',
                    'seo_description',
                    'seo_image_path',
                    'seo_robots',
                    'tracking_head_code',
                    'tracking_body_code',
                ] as $managedField) {
                    $nojaContent[$managedField] = $existingNoja->getAttribute($managedField);
                }
            }

            Template::query()->updateOrCreate(
                ['code' => self::NOJA_CODE],
                array_merge($nojaContent, [
                    'name' => 'قالب نوژا کاشت',
                    'is_active' => true,
                    'is_default' => false,
                ])
            );

            if (! Template::query()->where('is_default', true)->exists()) {
                $classic->forceFill([
                    'is_active' => true,
                    'is_default' => true,
                ])->save();
            }
        });
    }

