    /**
     * Preserve the CRLF line endings stored by the Noja template editor.
     *
     * @param  string  $html  Trusted template fragment.
     * @return string Template fragment with the database line endings.
     *
     * @since 2.1.0
     */
    private static function withDatabaseLineEndings(string $html): string
    {
        return str_replace("\n", "\r\n", str_replace(["\r\n", "\r"], "\n", $html));
    }
